AllocId:
AllocId(struct IdManager *manager)
{
    int index = 0;
    int end = 0;
    int id = 0;
    uint8 entry = 0;
    do { if (manager == (0)) { KPrintf("PARAM CHECK FAILED ...%s %d %s is NULL.\n", __FUNCTION__, 31, "manager"); while (1) ; } } while (0);
    end = (manager->id_max + 7) / 8;
    for (index = 0; index < end; index++)
        if (manager->id_map[index] != 0xff)
            break;
    if (index == end)
        return -1;
    id = index * 8;
    entry = manager->id_map[index];
    while (entry & 0x1) {
        id++;
        entry >>= 1;
    }
    if (id >= manager->id_max)
        return -1;
    manager->id_map[index] |= (0x1 << (id % 8));
    return id;
}

CriticalAreaLock:
CriticalAreaLock(void) {
    x_base lock;
    lock = DisableLocalInterrupt();
    KTaskOsAssignLockNest ++;
    return lock;
}

DoubleLinkListInsertNodeAfter:
DoubleLinkListInsertNodeAfter(DoubleLinklistType *linklist, DoubleLinklistType *linklist_node)
{
    linklist->node_next->node_prev = linklist_node;
    linklist_node->node_next = linklist->node_next;
    linklist->node_next = linklist_node;
    linklist_node->node_prev = linklist;
}

IdInsertObj:
IdInsertObj(struct IdManager *manager, struct IdNode *idnode)
{
    int id = 0;
    do { if (manager == (0)) { KPrintf("PARAM CHECK FAILED ...%s %d %s is NULL.\n", __FUNCTION__, 110, "manager"); while (1) ; } } while (0);
    do { if (idnode == (0)) { KPrintf("PARAM CHECK FAILED ...%s %d %s is NULL.\n", __FUNCTION__, 111, "idnode"); while (1) ; } } while (0);
    if ((id = AllocId(manager)) < 0)
        return -1;
    idnode->id = id;
    InsertObj(manager, idnode);
    return id;
}

InsertObj:
InsertObj(struct IdManager *manager, struct IdNode *idnode)
{
    do { if (manager == (0)) { KPrintf("PARAM CHECK FAILED ...%s %d %s is NULL.\n", __FUNCTION__, 64, "manager"); while (1) ; } } while (0);
    do { if (idnode == (0)) { KPrintf("PARAM CHECK FAILED ...%s %d %s is NULL.\n", __FUNCTION__, 65, "idnode"); while (1) ; } } while (0);
    DoubleLinklistType *head = &manager->htable[idnode->id % manager->hoffset];
    if (head->node_prev == (0))
        InitDoubleLinkList(head);
    DoubleLinkListInsertNodeAfter(head, &idnode->link);
}

_SemaphoreCreate:
_SemaphoreCreate(uint16 val)
{
    int32 id = 0;
    x_base lock = 0;
    struct Semaphore *sem = (0);
    sem = (struct Semaphore *)x_malloc(sizeof(struct Semaphore));
    if (sem == (0))
        return -5;
    memset(sem, 0, sizeof(struct Semaphore));
    lock = CriticalAreaLock();
    id = IdInsertObj(&k_sem_id_manager, &sem->id);
    if (id < 0) {
        x_free(sem);
        CriticalAreaUnLock(lock);
        return -5;
    }
    sem->value = val;
    InitDoubleLinkList(&sem->pend_list);
    DoubleLinkListInsertNodeAfter(&k_sem_list, &sem->link);
    CriticalAreaUnLock(lock);
    do { if (0) { KPrintf("[%s:%d] ", __func__, 59); KPrintf ("created semaphore: id %d, value %d\n", id, (int)val); } } while (0);
    return id;
}
